const cfg = $('Config').first().json;
const item = $input.first().json;
const b = item.body || item;
const pick = (...keys) => {
  for (const k of keys) {
    const v = b[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};

const fullName = pick('fullName', 'Full Name').replace(/\s+/g, ' ');
const rawEmail = pick('email', 'Email').toLowerCase();
const rawPhone = pick('phone', 'Phone');
const propertyType = pick('propertyType', 'Property Type');
const budgetRaw = pick('budget', 'Budget');
const location = pick('preferredLocation', 'Preferred Location');
const timeline = pick('buyingTimeline', 'Buying Timeline');
const message = pick('message', 'Message');
const submittedAt = pick('submittedAt', 'Timestamp') || new Date().toISOString();

// Email
const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(rawEmail);

// Phone -> E.164
const cc = cfg.defaultCountryCode || '+92';
const ccDigits = cc.replace('+', '');
const normPhone = (raw) => {
  if (!raw) return '';
  let s = raw.replace(/[^\d+]/g, '');
  if (s.startsWith('00')) s = '+' + s.slice(2);
  if (!s.startsWith('+')) {
    if (s.startsWith('0')) s = cc + s.slice(1);
    else if (s.startsWith(ccDigits) && s.length >= ccDigits.length + 9) s = '+' + s;
    else s = cc + s;
  }
  s = '+' + s.replace(/\+/g, '');
  return /^\+[1-9]\d{9,14}$/.test(s) ? s : '';
};
const phone = normPhone(rawPhone);
const phoneValid = phone !== '';

// Budget -> number (understands k, m, lakh, crore)
const parseBudget = (raw) => {
  if (!raw) return null;
  const s = raw.toLowerCase().replace(/,/g, '').replace(/(pkr|rs\.?|usd|aed|\$|£|€)/g, '').trim();
  const m = s.match(/(\d+(?:\.\d+)?)\s*(crore|cr|lakh|lac|million|mil|m|thousand|k)?\b/);
  if (!m) return null;
  const mult = { crore: 1e7, cr: 1e7, lakh: 1e5, lac: 1e5, million: 1e6, mil: 1e6, m: 1e6, thousand: 1e3, k: 1e3 };
  const n = parseFloat(m[1]) * (m[2] ? mult[m[2]] : 1);
  return n > 0 ? Math.round(n) : null;
};
const budget = parseBudget(budgetRaw);

// Validation
const authOk = !cfg.webhookSecret || b.secret === cfg.webhookSecret;
const flags = [];
if (!fullName) flags.push('Missing name');
if (!rawEmail) flags.push('Missing email');
else if (!emailValid) flags.push('Invalid email format');
if (!rawPhone) flags.push('Missing phone');
else if (!phoneValid) flags.push('Invalid phone number');

let rejectReason = '';
if (!authOk) rejectReason = 'Invalid webhook secret';
else if (!emailValid && !phoneValid) rejectReason = 'No valid email or phone number';

const raw = { ...b };
delete raw.secret;

return [{
  json: {
    fullName: fullName || 'Unknown lead',
    email: emailValid ? rawEmail : '',
    phone: phoneValid ? phone : '',
    rawEmail,
    rawPhone,
    propertyType,
    budgetRaw,
    budget,
    location,
    timeline,
    message,
    submittedAt,
    flags,
    authOk,
    isRejected: rejectReason !== '',
    rejectReason,
    dedupeColumnId: emailValid ? cfg.colEmail : cfg.colPhone,
    dedupeValue: emailValid ? rawEmail : phone,
    raw,
  },
}];

const cfg = $('Config').first().json;
const l = $input.first().json;
const tz = cfg.timezone || 'Asia/Karachi';
const reasons = [...(l.flags || [])];

const urgentWords = /(immediate|asap|right away|urgent|today|tomorrow|this week)/;
const undecidedWords = /(undecided|not sure|unsure|just looking|browsing|don't know|dont know|no idea|exploring|flexible)/;
const tl = (l.timeline || '').toLowerCase();
const msg = (l.message || '').toLowerCase();

let days = null;
let undecided = false;
if (!tl) {
  reasons.push('Missing buying timeline');
} else if (undecidedWords.test(tl)) {
  undecided = true;
} else if (urgentWords.test(tl)) {
  days = 7;
} else {
  const m = tl.match(/(\d+)(?:\s*-\s*(\d+))?\s*\+?\s*(day|week|month|year)/);
  if (m) {
    const unit = { day: 1, week: 7, month: 30, year: 365 }[m[3]];
    days = Number(m[2] || m[1]) * unit; // ranges use the upper bound
  } else {
    reasons.push('Unrecognised buying timeline: ' + l.timeline);
  }
}

if (!l.budget) reasons.push(l.budgetRaw ? 'Unreadable budget: ' + l.budgetRaw : 'Missing budget');
if ((undecided || (days !== null && days > 30)) && urgentWords.test(msg)) {
  reasons.push('Contradiction: timeline is "' + l.timeline + '" but the message sounds urgent');
}
if (days !== null && days <= 7 && /(just looking|only looking|browsing)/.test(msg)) {
  reasons.push('Contradiction: urgent timeline but the message says just browsing');
}

let priority;
if (reasons.length) priority = 'Needs review';
else if (undecided) priority = 'Nurture';
else if (days <= 7) priority = 'Urgent';
else if (days <= 30) priority = 'High priority';
else priority = 'Nurture';

const plan = {
  'Urgent': { action: 'Call the buyer within 1 hour, then confirm by email', dueDays: 0 },
  'High priority': { action: 'Call within 24 hours and propose viewing slots', dueDays: 1 },
  'Nurture': { action: 'Send property information within 3 days and add to the nurture list', dueDays: 3 },
  'Needs review': { action: 'Verify the missing or conflicting details, then re-classify', dueDays: 1 },
}[priority];
const followUpDue = $now.setZone(tz).plus({ days: plan.dueDays }).toFormat('yyyy-MM-dd');

// monday.com column values (only send what we have)
const cv = {};
if (l.email) cv[cfg.colEmail] = { email: l.email, text: l.email };
if (l.phone) cv[cfg.colPhone] = l.phone;
if (l.propertyType) cv[cfg.colPropertyType] = l.propertyType;
if (l.budget) cv[cfg.colBudget] = String(l.budget);
if (l.location) cv[cfg.colLocation] = l.location;
if (l.timeline) cv[cfg.colTimeline] = l.timeline;
if (l.message) cv[cfg.colMessage] = { text: l.message };
cv[cfg.colPriority] = { label: priority };
cv[cfg.colFollowUpDue] = { date: followUpDue };
if (cfg.salesRepMondayUserId && cfg.colOwner) {
  cv[cfg.colOwner] = { personsAndTeams: [{ id: Number(cfg.salesRepMondayUserId), kind: 'person' }] };
}
const createCV = { ...cv, [cfg.colStage]: { label: 'New' } }; // stage only set on creation
const updateCV = cv;

const lookupBody = JSON.stringify({
  query: 'query ($boardId: ID!, $col: String!, $val: String!) { items_page_by_column_values(board_id: $boardId, limit: 1, columns: [{column_id: $col, column_values: [$val]}]) { items { id name } } }',
  variables: { boardId: String(cfg.boardId), col: l.dedupeColumnId, val: l.dedupeValue },
});
const createBody = JSON.stringify({
  query: 'mutation ($boardId: ID!, $groupId: String, $name: String!, $cv: JSON!) { create_item(board_id: $boardId, group_id: $groupId, item_name: $name, column_values: $cv, create_labels_if_missing: true) { id } }',
  variables: { boardId: String(cfg.boardId), groupId: cfg.groupId || null, name: l.fullName, cv: JSON.stringify(createCV) },
});

return [{
  json: {
    ...l,
    priority,
    followUpAction: plan.action,
    followUpDue,
    reviewReasons: reasons,
    timelineDays: days,
    updateColumnValues: JSON.stringify(updateCV),
    lookupBody,
    createBody,
  },
}];

const cfg = $('Config').first().json;
const r = $input.first().json;
if (r.error_message || (r.errors && r.errors.length) || !r.data) {
  throw new Error('monday.com lookup failed: ' + JSON.stringify(r.errors || r.error_message || r).slice(0, 400));
}
const l = $('Classify Lead').first().json;
const items = (r.data.items_page_by_column_values && r.data.items_page_by_column_values.items) || [];
const existingItemId = items.length ? items[0].id : null;
const out = { ...l, hasExisting: !!existingItemId, existingItemId };
if (existingItemId) {
  out.updateBody = JSON.stringify({
    query: 'mutation ($boardId: ID!, $itemId: ID!, $cv: JSON!) { change_multiple_column_values(board_id: $boardId, item_id: $itemId, column_values: $cv, create_labels_if_missing: true) { id } }',
    variables: { boardId: String(cfg.boardId), itemId: String(existingItemId), cv: l.updateColumnValues },
  });
}
return [{ json: out }];

const cfg = $('Config').first().json;
const r = $input.first().json;
if (r.error_message || (r.errors && r.errors.length) || !r.data) {
  throw new Error('monday.com create/update failed: ' + JSON.stringify(r.errors || r.error_message || r).slice(0, 400));
}
const d = $('Parse Lookup').first().json;
const isDuplicate = !!r.data.change_multiple_column_values;
const itemId = (r.data.change_multiple_column_values || r.data.create_item).id;
const leadUrl = cfg.mondayAccountUrl.replace(/\/+$/, '') + '/boards/' + cfg.boardId + '/pulses/' + itemId;
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = d.budget ? d.budget.toLocaleString('en-US') : '—';

const logHtml = [
  '<b>' + (isDuplicate ? 'Repeat enquiry' : 'New enquiry') + ' received via Google Form</b>',
  'Priority: ' + esc(d.priority),
  'Follow-up: ' + esc(d.followUpAction) + ' (due ' + d.followUpDue + ')',
  'Budget: ' + money + ' | Timeline: ' + esc(d.timeline || '—') + ' | Location: ' + esc(d.location || '—'),
  'Property type: ' + esc(d.propertyType || '—'),
  'Message: ' + esc(d.message || '—'),
  d.reviewReasons.length ? 'Review flags: ' + esc(d.reviewReasons.join('; ')) : 'Review flags: none',
].join('<br>');

const logBody = JSON.stringify({
  query: 'mutation ($itemId: ID!, $body: String!) { create_update(item_id: $itemId, body: $body) { id } }',
  variables: { itemId: String(itemId), body: logHtml },
});

const taskCV = {};
if (cfg.taskDueColumnId) taskCV[cfg.taskDueColumnId] = { date: d.followUpDue };
if (cfg.taskNotesColumnId) taskCV[cfg.taskNotesColumnId] = d.followUpAction + ' | Lead: ' + leadUrl;
const taskBody = JSON.stringify({
  query: 'mutation ($boardId: ID!, $groupId: String, $name: String!, $cv: JSON!) { create_item(board_id: $boardId, group_id: $groupId, item_name: $name, column_values: $cv, create_labels_if_missing: true) { id } }',
  variables: {
    boardId: String(cfg.taskBoardId),
    groupId: cfg.taskGroupId || null,
    name: 'Follow up (' + d.priority + '): ' + d.fullName,
    cv: JSON.stringify(taskCV),
  },
});

const rows = [
  ['Name', d.fullName], ['Priority', d.priority], ['Follow-up action', d.followUpAction + ' (due ' + d.followUpDue + ')'],
  ['Email', d.email || '—'], ['Phone', d.phone || '—'], ['Property type', d.propertyType || '—'],
  ['Budget', money], ['Preferred location', d.location || '—'], ['Buying timeline', d.timeline || '—'],
  ['Message', d.message || '—'],
];
if (d.reviewReasons.length) rows.push(['Review flags', d.reviewReasons.join('; ')]);
const table = rows.map((x) => '<tr><td style="padding:6px 12px;background:#f5f5f5"><b>' + esc(x[0]) + '</b></td><td style="padding:6px 12px">' + esc(x[1]) + '</td></tr>').join('');
const emailHtml =
  '<div style="font-family:Arial,sans-serif;max-width:620px">' +
  '<h2>' + (isDuplicate ? 'Repeat enquiry (existing lead updated)' : 'New lead') + '</h2>' +
  '<table style="border-collapse:collapse;width:100%">' + table + '</table>' +
  '<p><a href="' + esc(leadUrl) + '" style="display:inline-block;padding:10px 18px;background:#0073ea;color:#fff;text-decoration:none;border-radius:4px">Open lead in monday.com</a></p>' +
  '<p style="color:#777;font-size:12px">Sent by the Real Estate Lead Response Agent. No message has been sent to the buyer.</p></div>';
const emailSubject = '[' + d.priority.toUpperCase() + '] ' + (isDuplicate ? 'Repeat enquiry' : 'New lead') + ': ' + d.fullName;

return [{ json: { itemId, isDuplicate, leadUrl, logBody, taskBody, emailHtml, emailSubject } }];

const bad = (x) => !x || x.error_message || (x.errors && x.errors.length) || !x.data;
const logRes = $('Log Enquiry Update').first().json;
const taskRes = $input.first().json;
if (bad(logRes)) throw new Error('monday.com update note failed: ' + JSON.stringify(logRes).slice(0, 400));
if (bad(taskRes)) throw new Error('monday.com follow-up task failed: ' + JSON.stringify(taskRes).slice(0, 400));
return [{ json: { taskItemId: taskRes.data.create_item.id } }];

const l = $input.first().json;
if (!l.authOk) return []; // bad secret: ignore silently, do not spam the admin
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const subject = '[REJECTED ENQUIRY] ' + l.rejectReason + ' - ' + l.fullName;
const html =
  '<div style="font-family:Arial,sans-serif;max-width:620px"><h2>Enquiry rejected by automation</h2>' +
  '<p><b>Reason:</b> ' + esc(l.rejectReason) + '</p>' +
  '<p>Nothing was written to monday.com. If the buyer can be reached some other way, add them manually.</p>' +
  '<pre style="background:#f5f5f5;padding:12px;white-space:pre-wrap">' + esc(JSON.stringify(l.raw, null, 2)) + '</pre></div>';
return [{ json: { subject, html } }];

const cfg = $('Config').first().json;
const first = $input.first().json;
const e = first.error || first;
const msg = typeof e === 'string' ? e : (e.message || e.description || JSON.stringify(e).slice(0, 500));
const step = (e && e.node && e.node.name) || (e && e.context && e.context.nodeName) || 'see the failed execution';
let lead = {};
for (const name of ['Parse Lookup', 'Classify Lead', 'Normalize & Validate']) {
  try { lead = $(name).first().json; break; } catch (err) { /* node not executed */ }
}
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = [
  ['Name', lead.fullName], ['Email', lead.email || lead.rawEmail], ['Phone', lead.phone || lead.rawPhone],
  ['Property type', lead.propertyType], ['Budget', lead.budgetRaw], ['Location', lead.location],
  ['Timeline', lead.timeline], ['Message', lead.message], ['Priority', lead.priority],
].map((x) => '<tr><td style="padding:4px 10px;background:#f5f5f5"><b>' + x[0] + '</b></td><td style="padding:4px 10px">' + esc(x[1] || '—') + '</td></tr>').join('');
const html =
  '<div style="font-family:Arial,sans-serif;max-width:640px"><h2 style="color:#c62828">Lead automation failed</h2>' +
  '<p><b>Step:</b> ' + esc(step) + '<br><b>Error:</b> ' + esc(msg) + '<br><b>n8n execution ID:</b> ' + esc($execution.id) + '</p>' +
  '<h3>Enquiry</h3><table style="border-collapse:collapse">' + rows + '</table>' +
  '<h3>Process it manually</h3><ol>' +
  '<li>Search the leads board in monday.com for the buyer\'s email or phone.</li>' +
  '<li>If it exists, update the fields above and set the priority. If not, create the item with stage "New".</li>' +
  '<li>Add a follow-up task on the tasks board using the priority rules (Urgent: call within 1 hour; High: 24 hours; Nurture: 3 days; Needs review: verify details).</li>' +
  '<li>Contact the buyer yourself. The automation never emails buyers.</li></ol>' +
  '<h3>Retry safely</h3><p>Open n8n, then Executions, open execution ' + esc($execution.id) + ' and use Retry. The duplicate check means a retry updates the existing lead instead of creating a second one. ' +
  'Exception: if the step above is "Email Sales Rep", the lead and task already exist, so do not retry. Just tell the sales rep yourself.</p></div>';
return [{ json: { subject: '[FAILED] Lead automation error at: ' + step, html } }];
